 5→// The route for a method and path, with its :params, or null.
 6→export function match(method, path) {
 7→  const parts = path.split("/").filter(Boolean);
 8→  for (const route of routes) {
 9→    const pattern = route.path.split("/").filter(Boolean);
10→    if (pattern.length !== parts.length || !route.methods.includes(method)) continue;
11→    const params = {};
12→    if (pattern.every((p, i) => (p.startsWith(":") ? ((params[p.slice(1)] = parts[i]), true) : p === parts[i]))) {
13→      return { handler: route.handler, params };
14→    }
15→  }
16→  return null;
17→}
